action.command:
cd /workspace && echo "=== Restart/health sweep ===" && docker compose ps --format '{{.Name}}\t{{.Status}}\tRestarts={{.Health}}' 2>/dev/null || docker ps --format '{{.Names}}\t{{.Status}}'
echo "=== Container RestartCount ==="
for c in $(docker ps -q); do n=$(docker inspect -f '{{.Name}} RestartCount={{.RestartCount}} State={{.State.Status}}' "$c"); echo "$n"; done | grep -E 'workspace|smtp'
echo "=== Dashboard compiled backend domain (NEXT_PUBLIC) sanity ==="
docker compose exec -T backend node -e '
(async () => {
  const r = await fetch("http://dashboard:3000/eckener-schule/login");
  const html = await r.text();
  // look for any embedded localhost:4000 (the NEXT_PUBLIC_CORE_BACKEND_DOMAIN)
  console.log("contains localhost:4000:", html.includes("localhost:4000") || html.includes("http%3A%2F%2Flocalhost%3A4000"));
  console.log("login page title:", (html.match(/<title>(.*?)<\/title>/)||[])[1]);
})();
'

